    for p in (observation.get("opponent_territory") or []):
        if p and len(p) >= 2:
            opp_set.add((p[0], p[1]))

    unclaimed = []
    for p in (observation.get("unclaimed_cells") or []):
        if p and len(p) >= 2:
            x, y = p[0], p[1]
            if inb(x, y) and (x, y) not in obstacles:
                unclaimed.append((x, y))

    # Candidate targets: unclaimed adjacent to opponent territory (flips on entry), else edge unclaimed.
    def neighbors8(x, y):
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if inb(nx, ny):
                    yield nx, ny

    frontier = []
    for (x, y) in unclaimed:
        for nx, ny in neighbors8(x, y):
            if (nx, ny) in opp_set:
                frontier.append((x, y))
                break

    edge_targets = [c for c in unclaimed if c[0] == 0 or c[0] == w - 1 or c[1] == 0 or c[1] == h - 1]
    targets = frontier if frontier else edge_targets if edge_targets else unclaimed
    if not targets:
        return [0, 0]

    # Deterministic target selection: nearest, tie-break by (x,y).
    target = min(targets, key=lambda c: (abs(c[0] - sx) + abs(c[1] - sy), c[0], c[1]))
    tx, ty = target

    # Choose move that minimizes distance to target while avoiding obstacles; if tie, prefer attacking (moving closer to opponent territory).
    opp_list = list(opp_set)

    def dist(a, b, c, d):
        return abs(a - c) + abs(b - d)

    best = None
    best_key = None
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                nx, ny = sx, sy
            else:
                nx, ny = sx + dx, sy + dy
            if not inb(nx, ny):
                continue
            if (nx, ny) in obstacles:
                continue

            d_to_t = dist(nx, ny, tx, ty)
            # Proximity to opponent territory (smaller is better). If no opp cells, keep neutral.
            d_to_opp = 0
            if opp_list:
                d_to_opp = min(dist(nx, ny, ox, oy) for ox, oy in opp_list)
            # Small penalty for getting "too close" to obstacles: count obstacle neighbors around next cell.
            obs_nei = 0
            for ax, ay in neighbors8(nx, ny):
                if (ax, ay) in obstacles:
                    obs_nei += 1

            key = (d_to_t, d_to_opp, obs_nei, -abs(dx) - abs(dy), nx, ny, dx, dy)
            if best_key is None or key < best_key:
                best_key = key
                best = [dx, dy]

    if best is None:
        return [0, 0]
    return [int(best[0]), int(best[1]]]

